create table xxcus.xxcmp_answer_options (
    answer_option_id       number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment
    by 1 cache 20 noorder nocycle nokeep noscale not null enable,
    question_id            number not null enable,
    lookup_type            varchar2(30 byte),
    lookup_code            varchar2(30 byte),
    answer_label           varchar2(240 byte),
    risk_points            number default 0 not null enable,
    critical_flag          varchar2(1 byte) default 'N' not null enable,
    waiver_qualifying_flag varchar2(1 byte) default 'N' not null enable,
    display_sequence       number,
    enabled_flag           varchar2(1 byte) default 'Y' not null enable,
    approval_status        varchar2(20 byte) default 'DRAFT' not null enable,
    approved_by            varchar2(255 byte),
    approved_date          timestamp(6),
    created_by             varchar2(255 byte) not null enable,
    creation_date          timestamp(6) not null enable,
    last_updated_by        varchar2(255 byte) not null enable,
    last_update_date       timestamp(6) not null enable,
    last_update_login      varchar2(255 byte),
    object_version_number  number default 1 not null enable
);

alter table xxcus.xxcmp_answer_options
    add constraint xxcmp_answer_options_ck1
        check ( critical_flag in ( 'Y', 'N' ) ) enable;

alter table xxcus.xxcmp_answer_options
    add constraint xxcmp_answer_options_ck2
        check ( waiver_qualifying_flag in ( 'Y', 'N' ) ) enable;

alter table xxcus.xxcmp_answer_options
    add constraint xxcmp_answer_options_ck3
        check ( enabled_flag in ( 'Y', 'N' ) ) enable;

alter table xxcus.xxcmp_answer_options
    add constraint xxcmp_answer_options_ck4
        check ( approval_status in ( 'DRAFT', 'PENDING_APPROVAL', 'APPROVED', 'REJECTED' ) ) enable;

alter table xxcus.xxcmp_answer_options
    add constraint xxcmp_answer_options_ck5
        check ( ( lookup_type is not null
                  and lookup_code is not null
                  and answer_label is null )
                or ( lookup_type is null
                     and lookup_code is null
                     and answer_label is not null ) ) enable;

alter table xxcus.xxcmp_answer_options
    add constraint xxcmp_answer_options_pk primary key ( answer_option_id )
        using index enable;


